  func getmntpt(_ name : String) -> String? {

    let mntbuf = getmntinfo()
    for mbi in mntbuf {
      if mbi.mntfromname == name {
        return mbi.mntonname
      }
    }
    return nil
  }

  func makevfslist(_ fslist : String?) -> (Bool, [String]) {
    var skip = false
    guard var fslist else {
      return (false, [])
    }

    if fslist.hasPrefix("no") {
      fslist.removeFirst(2)
      skip = true
    }
    return (skip, fslist.split(separator: ",").map { String($0) })
  }

  func checkvfsname(_ vfsname : String, _ vfslist : [String]?, _ skip : Bool) -> Bool  {
    guard let vfslist else {
      return false
    }
    if vfslist.contains(vfsname) { return skip }
    else { return (!skip) }
  }

  /*
   * Without -l and -t option, all file system types are enabled.
   * The -l option selects the local file systems, if present.
   * A -t option modifies the selection by adding or removing further
   * file system types, based on the argument that is passed.
   */
  func checkvfsselected(_ fstypename : String) -> Bool {
    var result = false
    if let ov = options.vfslist_t {
      /* if -t option used then select passed types */
      result = checkvfsname(fstypename, ov, options.skipvfs_t)
      if let ol = options.vfslist_l {
        /* if -l option then adjust selection */
        if checkvfsname(fstypename, ol, options.skipvfs_l) == result {
          result = options.skipvfs_t
        }
      }
    } else {
      /* no -t option then -l decides */
      result = checkvfsname(fstypename, options.vfslist_l, options.skipvfs_l);
    }
    return result
  }

