  func prthuman(_ sfsp : FileSystemMetadata, _ used : Int) {
    let buf = prthumanval(Int(sfsp.blocks) * Int(sfsp.bsize))
    xo_emit("  {:blocks/\(buf.leftPad(toLength: 6))}")
    let buf2 = prthumanval(Int(used) * Int(sfsp.bsize))
    xo_emit("  {:used/\(buf2.leftPad(toLength: 6))}")
    let buf3 = prthumanval(Int(sfsp.bavail) * Int(sfsp.bsize))
    xo_emit("  {:available/\(buf3.leftPad(toLength: 6))}")
  }

  func prthumanval(_ bytes : Int) -> String {
    /*#ifndef __APPLE__
     char buf[6];
     #else
     */
    // #endif

    var flags : HumanizeFlags = [.b, .nospace, .decimal]
    if (options.hflag == UNITS_SI) {
      flags.insert(.divisor_1000)
    }

    /*
     #ifndef __APPLE__
     humanize_number(buf, sizeof(buf) - (bytes < 0 ? 0 : 1),
     bytes, "", HN_AUTOSCALE, flags);
     #else
     */
    let buf = humanize_number(7 - (bytes < 0 ? 0 : 1),
                              bytes, options.hflag == UNITS_SI ? "" : "i", nil, flags)
    // #endif
    xo_attr("value", String(bytes))
    return buf!
  }

  /*
   * Print an inode count in "human-readable" format.
   */
  func prthumanvalinode(_ bytes : Int) -> String {
    let flags : HumanizeFlags = [.nospace, .decimal, .divisor_1000]

    let buf = humanize_number(6 - (bytes < 0 ? 0 : 1), bytes, "", nil, flags)

    xo_attr("value", String(bytes))
    return buf!
  }

  /*
   * Convert statfs returned file system size into BLOCKSIZE units.
   * Attempts to avoid overflow for large filesystems.
   */
  func fsbtoblk(_ num : UInt, _ fsbs : UInt, _ bs : UInt, _ fs : String) -> UInt {
    if ((fsbs != 0) && (fsbs < bs)) {
      return (num / (bs / fsbs))
    } else {
      return (num * (fsbs / bs))
    }
  }

  func usedblks(_ sfsp : FileSystemMetadata) -> Int {

    /* Call getattrlist(ATTR_VOL_SPACEUSED) to get used space info. */

    struct Attrbuf {
      var size : UInt32 = 0
      var spaceused : UInt64 = 0
    }

    var attrbuf = Attrbuf()
    var attrs = attrlist()
    attrs.bitmapcount = UInt16(ATTR_BIT_MAP_COUNT)
    attrs.volattr = ATTR_VOL_INFO | UInt32(ATTR_VOL_SPACEUSED)
    if (getattrlist(sfsp.mntonname, &attrs, &attrbuf, MemoryLayout.size(ofValue: attrbuf), 0) != 0) {
      if (errno != EINVAL) {
        xo_warn("getattrlist failed for \(sfsp.mntonname)")
      }
      return Int(sfsp.blocks - sfsp.bfree)
    }

    /* The structure passed isn't entirely filled out -
     but use the preferred default value. */
    if (sfsp.bsize == 0) {
      return Int(attrbuf.spaceused) / Int(blocksize)
    }

    return Int(attrbuf.spaceused) / Int(sfsp.bsize)
  }

  /*
   * Print out status about a file system.
   */
  func prtstat(_ sfsp : FileSystemMetadata, _ mwp : inout maxwidths, _ tto : Bool) {
/*    static long blocksize;
    static int headerlen, timesthrough = 0;
    static const char *header;
    int64_t used, availblks, inodes;
    const char *format;
    const char *avail_str;
*/
    if tto {
      mwp.mntfrom = max(mwp.mntfrom, strlen("Filesystem"))
      mwp.fstype = max(mwp.fstype, strlen("Type"))
      if (options.thousands) {		/* make space for commas */
        mwp.total += (mwp.total - 1) / 3;
        mwp.used  += (mwp.used - 1) / 3;
        mwp.avail += (mwp.avail - 1) / 3;
        mwp.iused += (mwp.iused - 1) / 3;
        mwp.ifree += (mwp.ifree - 1) / 3;
      }

      var header : String
      if 0 != options.hflag {
        header = "   Size";
        mwp.total = header.count
        mwp.used = header.count
        mwp.avail = header.count
      } else {
        mwp.total = max(mwp.total, Int(hlen))
        header = head
      }

      mwp.used = max(mwp.used, "Used".count)

      var avail_str : String
      if unix2003 && 0 == options.hflag {
        avail_str = "Available"
      } else {
        avail_str = "Avail"
      }
      mwp.avail = max(mwp.avail, strlen(avail_str))

      xo_emit("{T:/\("Filesystem".rightPad(toLength: mwp.mntfrom))}")
      if options.Tflag {
        xo_emit("  {T:/\("Type".rightPad(toLength: mwp.fstype))}")
      }
      xo_emit(" {T:/\(header.leftPad(toLength: mwp.total))} {T:/\("Used".leftPad(toLength: mwp.used))} {T:/\(avail_str.leftPad(toLength: mwp.avail))} {T:Capacity}")
      if options.iflag {
        mwp.iused = max(options.hflag != 0 ? 0 : mwp.iused, "  iused".count)
        mwp.ifree = max(options.hflag != 0 ? 0 : mwp.ifree, "ifree".count)
        xo_emit(" {T:/\("iused".leftPad(toLength: mwp.iused-2))} {T:/\("ifree".leftPad(toLength:mwp.ifree))} {T:\\%iused}")
      }
      xo_emit("  {T:Mounted on}\n");
    }

    xo_open_instance("filesystem");
    /* Check for 0 block size.  Can this happen? */
    xo_emit("{tk:name/\(sfsp.mntfromname.rightPad(toLength: mwp.mntfrom))}")
    if options.Tflag {
      xo_emit("  {:type/\(sfsp.fstypename.rightPad(toLength: mwp.fstype))}")
    }
    let used = (sfsp.blocks > sfsp.bfree) ? usedblks(sfsp) : 0

    let availblks = sfsp.bavail + UInt(used)
    if options.hflag != 0 {
      prthuman(sfsp, used);
    } else {
      let cc = options.thousands ? "%*j'd" : "%*jd"
      let buf1 = cc.cFormat(mwp.total, fsbtoblk(sfsp.blocks, sfsp.bsize, blocksize, sfsp.mntonname))
      let buf2 = cc.cFormat(mwp.used, fsbtoblk(UInt(used), sfsp.bsize, blocksize, sfsp.mntonname))
      let buf3 = cc.cFormat(mwp.avail, fsbtoblk(sfsp.bavail, sfsp.bsize, blocksize, sfsp.mntonname))
      let format = " {t:total-blocks/\(buf1)} {t:used-blocks/\(buf2)} {t:available-blocks/\(buf3)}"
      xo_emit(format)
    }
    if unix2003 {
      /* Standard says percentage must be rounded UP to next
       integer value, not truncated */
      var value : Double
      if availblks == 0 {
        value = 100.0
      }
      else {
        value = Double(used) / Double(availblks) * 100.0
        if ((value - Double(Int(value))) > 0.0) {
          value = value + 1.0
        }
      }
      xo_emit(" {:used-percent/%5.0f}{U:%%}", trunc(value));
    } else {
      let x = availblks == 0 ? 100.0 : Double(used) / Double(availblks) * 100.0
      xo_emit(" {:used-percent/%5.0f}{U:%%}", x)
    }
    if options.iflag {
      let inodes = sfsp.files
      let used = inodes - sfsp.ffree
      if 0 != options.hflag {
        xo_emit("  ");
        let buf = prthumanvalinode(Int(used))
        xo_emit(" {:inodes-used/\(buf.leftPad(toLength: 5))}")
        let buf2 = prthumanvalinode(Int(sfsp.ffree))
        xo_emit(" {:inodes-free/\(buf2.leftPad(toLength: 5))}")
      } else {
        let cc = options.thousands ? "%*j'd" : "%*jd"
        let buf1 = cc.cFormat(mwp.iused, used)
        let buf2 = cc.cFormat(mwp.ifree, sfsp.ffree)
        let format = " {:inodes-used/\(buf1)} {:inodes-free/\(buf2)}"
        xo_emit(format)
      }
      if (inodes == 0) {
        xo_emit(" {:inodes-used-percent/    -}{U:} ");
      }
      else {
        xo_emit(" {:inodes-used-percent/%4.0f}{U:%%} ",
                Double(used) / Double(inodes) * 100.0);
      }
    } else {
      xo_emit("  ");
    }
    if sfsp.mntfromname != "total" {
      xo_emit("  {:mounted-on/\(sfsp.mntonname)}")
    }
    xo_emit("\n");
    xo_close_instance("filesystem");
  }

  func addstat(_ totalfsp : inout FileSystemMetadata, _ statfsp : FileSystemMetadata) {
    let bsize = statfsp.bsize / totalfsp.bsize
    totalfsp.blocks += statfsp.blocks * bsize
    totalfsp.bfree += statfsp.bfree * bsize
    totalfsp.bavail += statfsp.bavail * bsize
    totalfsp.files += statfsp.files
    totalfsp.ffree += statfsp.ffree
  }

  var (head, hlen, blocksize) = {
    var dummy : Int32 = 0
    var bs : UInt = 0
    let h = Darwin.getbsize(&dummy, &bs)
    return (String(cString: h!), dummy, bs)
  }()

  /*
   * Update the maximum field-width information in `mwp' based on
   * the file system specified by `sfsp'.
   */
  func update_maxwidths(_ mwp : inout maxwidths, _ sfs : FileSystemMetadata) {
//    var sfsp = sfs

    mwp.mntfrom = max(mwp.mntfrom, sfs.mntfromname.count)
    mwp.fstype = max(mwp.fstype, sfs.fstypename.count)
    mwp.total = max(mwp.total, uint64width(fsbtoblk(sfs.blocks, sfs.bsize, blocksize, sfs.mntonname)))
    mwp.used = max(mwp.used, uint64width(fsbtoblk(sfs.blocks - sfs.bfree, sfs.bsize, blocksize, sfs.mntonname)))
    mwp.avail = max(mwp.avail, uint64width(fsbtoblk(sfs.bavail, sfs.bsize, blocksize, sfs.mntonname)))
    mwp.iused = max(mwp.iused, uint64width(sfs.files - sfs.ffree))
    mwp.ifree = max(mwp.ifree, uint64width(sfs.ffree))
  }

  /* Return the width in characters of the specified value. */
  func int64width(_ valx : Int) -> Int {
    var len = 0
    var val = valx
    /* Negative or zero values require one extra digit. */
    if (val <= 0) {
      val = -val
      len += 1
    }
    while (val > 0) {
      len += 1
      val /= 10
    }

    return len
  }


  func uint64width(_ valx : UInt) -> Int {
    var len = 0
    var val = valx
    while (val > 0) {
      len += 1
      val /= 10
    }
    return len
  }





